import React from "react";
import SubHeading from "../../../Components/Heading/SubHeading";
import muc from "./mercury-11591_640.png";

function Section4() {
  let obj = [
    {
      planet: "Mercury",
      img: muc,
      para: "Mercury, the smallest planet in the solar system, is closest to the Sun and has an extreme environment with dramatic temperature fluctuations, ranging from scorching 430°C (800°F) during the day to freezing -180°C (-290°F) at night. Its surface is heavily cratered, resembling the Moon, with features like the massive Caloris Basin and cliffs formed by the planet's contraction. Mercury has a high density due to its large iron core, which makes up about 85% of its radius, and it possesses a weak magnetic field. A day on Mercury lasts 59 Earth days, while its year is only 88 Earth days, creating unique sunrise and sunset patterns. Missions like NASA's MESSENGER and the ongoing BepiColombo project have greatly advanced our understanding of this enigmatic, airless world.",
    },
  ];

  const solarSystemPlanets = [
    "Mercury",
    "Venus",
    "Earth",
    "Mars",
    "Jupiter",
    "Saturn",
    "Uranus",
    "Neptune",
  ];

  return (
    <div className=" w-full h-screen relative mt-44 justify-center flwx ">
      <SubHeading text="Solar System Planets" />
      {obj.map((ele) => {
        return (
          <div className=" border-2 border-yellow-400 ">
            <p className=" text-white">{ele.para}</p>
          </div>
        );
      })}
    </div>
  );
}

export default Section4;
